if [[ -n "$ARGC_COMPLETIONS_ROOT" && -f "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh" ]]; then
    . "$ARGC_COMPLETIONS_ROOT/utils/_argc_utils.sh"
fi

_choice_command() {
    if _argc_util_has_path_prefix; then
        _argc_util_comp_path
        return 0
    fi
    _argc_util_comp_command
}

_choice_command_args() {
    if [[ "${#argc__positionals[@]}" -lt 3 ]]; then
        _choice_command
    else
        _argc_util_comp_subcommand 1
    fi
}

_choice_mcp_server() {
    local file
    for file in "${PI_CODING_AGENT_DIR:-$HOME/.pi/agent}/mcp.json" .pi/mcp.json; do
        if [[ -f "$file" ]]; then
            jq -b -r '.mcpServers // {} | keys[]' "$file" 2>/dev/null
        fi
    done
}

_choice_model() {
    _argc_util_cache 600 _choice_model_uncached "pi_models_${argc_provider:-all}"
}

_choice_model_uncached() {
    local provider="${argc_provider:-}"
    pi --list-models 2>/dev/null | gawk -v provider="$provider" '
        NR > 1 && NF > 1 {
            if (provider == "") {
                print $1 "/" $2 "\t" $3 " ctx, " $4 " out"
            } else if ($1 == provider) {
                print $2 "\t" $3 " ctx, " $4 " out"
            }
        }'
}

_choice_models() {
    _choice_model | _argc_util_comp_multi ,
}

_choice_package() {
    local settings
    for settings in "${PI_CODING_AGENT_DIR:-$HOME/.pi/agent}/settings.json" .pi/settings.json; do
        if [[ -f "$settings" ]]; then
            jq -b -r '.packages[]? | if type == "object" then (.source // empty) else . end' "$settings" 2>/dev/null
        fi
    done
}

_choice_provider() {
    _argc_util_cache 600 _choice_provider_uncached pi_providers
}

_choice_provider_uncached() {
    pi --list-models 2>/dev/null | gawk 'NR > 1 && NF { print $1 }'
}

_choice_session_id() {
    local dir="${argc_session_dir:-${PI_CODING_AGENT_SESSION_DIR:-${PI_CODING_AGENT_DIR:-$HOME/.pi/agent}/sessions}}"
    if [[ -d "$dir" ]]; then
        find "$dir" -type f -name '*.jsonl' 2>/dev/null | gawk -F/ '
            {
                name = $NF
                sub(/\.jsonl$/, "", name)
                count = split(name, parts, "_")
                if (count > 1) {
                    print parts[count]
                }
            }' | head -n 200
    fi
}

_choice_tool() {
    {
        printf '%s\n' read bash powershell edit write grep find ls
        _choice_mcp_server | gawk '{ print "mcp__" $0 "__*" }'
    } | _argc_util_comp_multi ,
}

_choice_update_source() {
    printf 'self\tUpdate pi only (alias for pi)\n'
    printf 'pi\tUpdate pi only\n'
    _choice_package
}
